import os
import sys
from translate_helper import process_and_save_category

def create_items(words_with_data):
    items = []
    seen = set()
    for w, s, u, diff in words_with_data:
        w_clean = w.strip().lower()
        if w_clean in seen:
            continue
        seen.add(w_clean)
        items.append({
            "word": w.strip(),
            "sentence": s.strip(),
            "usage": u.strip(),
            "difficulty": diff
        })
    return items

